  i18n_tokensaver_codexCaption: { zh: "Codex 属于 OpenAI 兼容接入，地址需要带 /v1。", en: "Codex uses OpenAI-compatible access — the URL must include /v1.", fr: "Codex utilise un accès compatible OpenAI — l'URL doit inclure /v1.", ru: "Codex использует доступ, совместимый с OpenAI — URL должен включать /v1.", ja: "CodexはOpenAI互換アクセスを使用します。URLに/v1を含める必要があります。", vi: "Codex sử dụng truy cập tương thích OpenAI — URL phải bao gồm /v1." },
  i18n_tokensaver_claudeLatestAlt: { zh: "CC Switch Claude Code 配置示例", en: "CC Switch Claude Code configuration example", fr: "Exemple de configuration CC Switch Claude Code", ru: "Пример конфигурации CC Switch Claude Code", ja: "CC Switch Claude Code設定例", vi: "Ví dụ cấu hình CC Switch Claude Code" },
  i18n_tokensaver_claudeLatestCaption: { zh: "Claude Code 属于 Claude/Anthropic 兼容接入，地址一般使用根地址。", en: "Claude Code uses Claude/Anthropic-compatible access — the root URL is typically used.", fr: "Claude Code utilise un accès compatible Claude/Anthropic — l'URL racine est généralement utilisée.", ru: "Claude Code использует доступ, совместимый с Claude/Anthropic — обычно используется корневой URL.", ja: "Claude CodeはClaude/Anthropic互換アクセスを使用します。通常はルートURLを使用します。", vi: "Claude Code sử dụng truy cập tương thích Claude/Anthropic — URL gốc thường được sử dụng." },

