  // ======================== 任务与异步能力 ========================
  i18n_tokensaver_tasksTitle: { zh: "任务与异步能力", en: "Tasks & Async Capabilities", fr: "Tâches et capacités asynchrones", ru: "Задачи и асинхронные возможности", ja: "タスクと非同期機能", vi: "Tác vụ & Khả năng bất đồng bộ" },
  i18n_tokensaver_tasksLead: { zh: "视频生成、音乐生成、部分绘图和长任务接口通常不是一次请求立即返回最终结果，而是先提交任务，再轮询或查询任务状态。", en: "Video generation, music generation, certain image generation, and long-running task APIs typically do not return final results immediately from a single request. Instead, you submit a task first, then poll or query the task status.", fr: "Les API de génération vidéo, de génération musicale, de certaines générations d'images et de tâches longues ne renvoient généralement pas le résultat final immédiatement. Au lieu de cela, vous soumettez d'abord une tâche, puis interrogez son statut.", ru: "API генерации видео, музыки, некоторых изображений и длительных задач обычно не возвращают конечный результат сразу. Вместо этого вы сначала отправляете задачу, а затем опрашиваете её статус.", ja: "動画生成、音楽生成、一部の画像生成、長時間タスクAPIは通常、1回のリクエストで最終結果を即座に返しません。代わりに、まずタスクを送信し、その後ステータスをポーリングまたはクエリします。", vi: "API tạo video, tạo nhạc, một số tạo hình ảnh và tác vụ dài thường không trả về kết quả cuối cùng ngay lập tức từ một yêu cầu. Thay vào đó, bạn gửi tác vụ trước, sau đó thăm dò hoặc truy vấn trạng thái tác vụ." },

  // ======================== 控制台指南 ========================
  i18n_tokensaver_consoleTitle: { zh: "控制台指南", en: "Console Guide", fr: "Guide de la console", ru: "Руководство по консоли", ja: "コンソールガイド", vi: "Hướng dẫn bảng điều khiển" },
  i18n_tokensaver_consoleLead: { zh: "TokenSaver 控制台提供概览、数据看板、API 密钥、使用日志、钱包和个人资料等入口。", en: "The TokenSaver console provides access to overview, data dashboard, API keys, usage logs, wallet, and profile.", fr: "La console TokenSaver donne accès à l'aperçu, au tableau de bord des données, aux clés API, aux journaux d'utilisation, au portefeuille et au profil.", ru: "Консоль TokenSaver предоставляет доступ к обзору, панели данных, ключам API, журналам использования, кошельку и профилю.", ja: "TokenSaverコンソールは、概要、データダッシュボード、APIキー、使用ログ、ウォレット、プロフィールへのアクセスを提供します。", vi: "Bảng điều khiển TokenSaver cung cấp quyền truy cập vào tổng quan, bảng dữ liệu, khóa API, nhật ký sử dụng, ví và hồ sơ." },

  // ======================== 使用日志 ========================
  i18n_tokensaver_logsTitle: { zh: "使用日志", en: "Usage Logs", fr: "Journaux d'utilisation", ru: "Журналы использования", ja: "使用ログ", vi: "Nhật ký sử dụng" },
  i18n_tokensaver_logsLead: { zh: "使用日志是排查问题的第一现场。它能确认请求是否到达、使用了哪个令牌和模型、耗时、Tokens、费用以及缓存情况。", en: "Usage logs are the first place to troubleshoot issues. They confirm whether a request arrived, which token and model were used, latency, tokens, cost, and cache status.", fr: "Les journaux d'utilisation sont le premier endroit pour résoudre les problèmes. Ils confirment si une requête est arrivée, quel jeton et modèle ont été utilisés, la latence, les tokens, le coût et l'état du cache.", ru: "Журналы использования — это первое место для устранения неполадок. Они подтверждают, поступил ли запрос, какой токен и модель использовались, задержку, токены, стоимость и состояние кэша.", ja: "使用ログは問題のトラブルシューティングの第一現場です。リクエストが到達したか、どのトークンとモデルが使用されたか、レイテンシ、トークン、コスト、キャッシュ状況を確認できます。", vi: "Nhật ký sử dụng là nơi đầu tiên để khắc phục sự cố. Chúng xác nhận yêu cầu đã đến chưa, token và mô hình nào đã được sử dụng, độ trễ, token, chi phí và trạng thái bộ nhớ đệm." },
  i18n_tokensaver_logsAlt: { zh: "TokenSaver 使用日志页面", en: "TokenSaver usage logs page", fr: "Page des journaux d'utilisation TokenSaver", ru: "Страница журналов использования TokenSaver", ja: "TokenSaver 使用ログページ", vi: "Trang nhật ký sử dụng TokenSaver" },
  i18n_tokensaver_logsCaption: { zh: "截图中可见时间范围、模型名称、分组、类型筛选、用量、RPM、TPM、耗时、Tokens、费用和详情。", en: "The screenshot shows time range, model name, group, type filter, usage, RPM, TPM, latency, tokens, cost, and details.", fr: "La capture d'écran montre la plage horaire, le nom du modèle, le groupe, le filtre de type, l'utilisation, RPM, TPM, la latence, les tokens, le coût et les détails.", ru: "На скриншоте видны временной диапазон, название модели, группа, фильтр типа, использование, RPM, TPM, задержка, токены, стоимость и детали.", ja: "スクリーンショットには、時間範囲、モデル名、グループ、タイプフィルター、使用量、RPM、TPM、レイテンシ、トークン、コスト、詳細が表示されています。", vi: "Ảnh chụp màn hình hiển thị phạm vi thời gian, tên mô hình, nhóm, bộ lọc loại, mức sử dụng, RPM, TPM, độ trễ, token, chi phí và chi tiết." },

  // ======================== 错误码 ========================
  i18n_tokensaver_errorsTitle: { zh: "错误码", en: "Error Codes", fr: "Codes d'erreur", ru: "Коды ошибок", ja: "エラーコード", vi: "Mã lỗi" },
